let browserCompatMode = false;
if(typeof window !== "undefined" && typeof document !== "undefined") browserCompatMode = true;
if(!browserCompatMode) WebSocket = require('ws');
if(browserCompatMode) {
	window.connector = {};
	exports = window.connector;
}
let state = {subscriptions:[]};
let connRetry = 2;
let clientMap = new Map();
let onopenFired,pending_reconnect = false;
exports.state = state;

function genSID() {
	return Math.random().toString().substr(-9).match(/.{1,3}/g).join('-');
}

exports.connect = function(opts,is_retry=false) {
	if(state.ws?.readyState == 1) throw "ALREADY_CONNECTED";
	console.log(opts);
	if(!opts.server) throw "NO_ADDR";
	if(!state.sid) state.sid = opts.id ? `${opts.id}_${genSID()}` : `unknown_${genSID()}`;
	onopenFired = false;
	if(!is_retry) state.failedConnections = 0;
	state.lastOpts = opts;
	state.ws = new WebSocket(opts.server);
	state.ws.onerror = _openfail;
	state.ws.onclose = _openfail;
	state.ws.onmessage = _onmessage;
	state.ws.onopen = _onopen;
	state.gotHbReply = false;
}

exports.on = function(tagName,func) {
	state.subscriptions.push(tagName);
	sendSubs();
	if(!clientMap.has(tagName)) {
		clientMap.set(tagName,[]);
	}
	clientMap.set(tagName,clientMap.get(tagName).concat([func]));
}

exports.hook = function(func) {
	state.hook = func;
}

exports.unsubscribe = function(tagName) {
	state.subscriptions = state.subscriptions.filter(a => a !== tagName);
	clientMap.delete(tagName);
	sendSubs();
}

function sendSubs() {
	if(!state) return;
	if(!state.ws) return;
	if(state.ws?.readyState == 0) return;
	state.ws.send(JSON.stringify({
		intent: "update_subscriptions",
		subscriptions: state.subscriptions
	}));
}

exports.forceSubscriptionUpdate = sendSubs;

function _onopen() {
	onopenFired = true;
	authenticated = false;
	state.ws.onerror = _onerror;
	state.ws.onclose = _onerror;
	if(state.hbTimer) clearInterval(state.hbTimer);
	state.hbTimer = setInterval(heartbeat,5000);
	state.ws.send(JSON.stringify({
		intent: "hello",
		sid: state.sid
	}));
}

function _onerror() {
	console.log("connection error");
	if(!browserCompatMode) {
		state.ws.terminate();
	} else {
		state.ws.close();
	}
	exports.connect(state.lastOpts,true);
}

function _openfail(e) {
	// console.log(e);
	if(pending_reconnect) return;
	console.log(`Failed to open WebSocket connection to server. Retrying in ${connRetry} seconds.`);
	pending_reconnect = setTimeout(_=>{exports.connect(state.lastOpts,true); pending_reconnect = false;},connRetry*1000);
	connRetry *= 2;
	if(connRetry > 300) connRetry = 300;
}

function _onmessage(e) {
	try {
		o = JSON.parse(e.data);
	} catch(err) {
		throw "INVALID_JSON";
	}
	if(state.hook) state.hook(o);
	if(o.intent == "message" && o.tag == "init") {
		sendSubs();
	}
	if(o.intent == "message" && o.tag && clientMap.has(o.tag)) {
		notify = clientMap.get(o.tag);
		notify.forEach(e => {
			e(o);
		});
	} else if(o.intent == "pong") {
		state.gotHbReply = true;
	}
}

function heartbeat() {
	state.gotHbReply = false;
	state.ws.send(JSON.stringify({
		"intent": "ping"
	}));
	setTimeout(_ => {
		if(!state.gotHbReply) {
			console.log("heartbeat timed out");
			_onerror();
		}
	},1000);
}

exports.send = function(data,tag=false) {
	if(typeof data == "object") data = JSON.stringify(data);
	try {
		let msg = {
			intent: "message",
			msg: data,
			sid: state.sid,
			tag
		}
		state.ws.send(JSON.stringify(msg));
		return msg;
	} catch(e) {
		queue(data,tag);
	}
}

function queue(data,tag) {
	console.log(`send failed, retrying...`);
	setTimeout(_=>{
		exports.send(data,tag);
	},1000);
}
